INSERT INTO `song_arrangements` VALUES (1, 2, 'Elshaddai', NULL, '76', '4/4', 'Intro, V1, C, V1, C2x Ending', 'C', 'Verse\r\nYesus, Kau sungguh baik\r\nYesus, nama-Mu indah\r\nYesus, kucinta Kau selalu\r\nKutinggikan, kuagungkan selamanya\r\n\r\n\r\nChorus\r\n\'Ku mau memuji-Mu, \'ku selalu puji-Mu\r\n\'Ku mau menyembah-Mu, \'ku selalu sembah-Mu\r\nKau yang layak t\'rima semua pujian\r\nKemuliaan hanya bagi Tuhan', NULL, 'https://www.youtube.com/watch?v=gJwI9D9cFzg', 'songs/pdf/ia90BguPAokgBpA6bL74HC5A0eh4G98cvkJr5P4l.pdf', 1, 0, 1, 0, '2026-08-20 11:25:19', '2026-08-20 11:34:43');
