INSERT INTO `song_arrangements` VALUES (3, 2, 'Elshaddai (Copy)', NULL, '76', '4/4', 'Intro, V1, C, V1, C2x Ending', 'C', 'Verse\r\nYesus, Kau sungguh baik\r\nYesus, nama-Mu indah\r\nYesus, kucinta Kau selalu\r\nKutinggikan, kuagungkan selamanya\r\n\r\n\r\nChorus\r\n\'Ku mau memuji-Mu, \'ku selalu puji-Mu\r\n\'Ku mau menyembah-Mu, \'ku selalu sembah-Mu\r\nKau yang layak t\'rima semua pujian\r\nKemuliaan hanya bagi Tuhan', NULL, 'https://www.youtube.com/watch?v=gJwI9D9cFzg', 'songs/pdf/d50dc1ba-4b09-43d1-9dee-362bd4a23a50.pdf', 1, 0, 1, 0, '2026-08-20 11:38:25', '2026-08-20 11:38:25');
INSERT INTO `song_arrangements` VALUES (4, 3, 'Tagor', NULL, '8.25', '4/4', 'Intro, V1, V2, PC, C1, C2, V1, V2, PC, C1, C2, PC, C1, C2, Ending', 'C-D', 'Verse 1\r\n\'Tak terbayang kebesaran-Mu\r\nDan \'tak terbanding kekuatan-Mu, Tuhan\r\nKau megah bagiku\r\n\r\n\r\nVerse 2\r\nSeg\'nap jiwa dan pengharapan\r\nT\'lah kuserahkan \'tuk rencana-Mu, Tuhan\r\n\'Kau Raja atasku\r\n\r\n\r\nPre-Chorus\r\nHanya \'Kau yang layak di tinggikan\r\n\r\n\r\nChorus 1\r\nAjaib \'Kau Tuhan\r\nAgung dan perkasa\r\n\'Kau sumber kemenanganku\r\n\r\n\r\nChorus 2\r\nLayak berkuasa\r\nMem\'rintah s\'lamanya\r\nYesus Kaulah Raja mulia', NULL, NULL, NULL, 1, 0, 0, 0, '2026-08-20 12:16:46', '2026-08-27 12:07:08');
INSERT INTO `song_arrangements` VALUES (5, 3, 'Elsa', NULL, '8.25', '4/4', 'Intro, V1, V2, PC, C1, C2, V1, V2, PC, C1, C2, PC, C1, C2, Ending', 'E', 'Verse 1\r\n\'Tak terbayang kebesaran-Mu\r\nDan \'tak terbanding kekuatan-Mu, Tuhan\r\nKau megah bagiku\r\n\r\n\r\nVerse 2\r\nSeg\'nap jiwa dan pengharapan\r\nT\'lah kuserahkan \'tuk rencana-Mu, Tuhan\r\n\'Kau Raja atasku\r\n\r\n\r\nPre-Chorus\r\nHanya \'Kau yang layak di tinggikan\r\n\r\n\r\nChorus 1\r\nAjaib \'Kau Tuhan\r\nAgung dan perkasa\r\n\'Kau sumber kemenanganku\r\n\r\n\r\nChorus 2\r\nLayak berkuasa\r\nMem\'rintah s\'lamanya\r\nYesus Kaulah Raja mulia', NULL, NULL, NULL, 1, 0, 0, 0, '2026-08-20 12:23:44', '2026-08-20 12:23:57');
INSERT INTO `song_arrangements` VALUES (6, 3, 'Imelda', NULL, '8.25', '4/4', 'Intro, V1, V2, PC, C1, C2, V1, V2, PC, C1, C2, PC, C1, C2, Ending', 'E', 'Verse 1\r\n\'Tak terbayang kebesaran-Mu\r\nDan \'tak terbanding kekuatan-Mu, Tuhan\r\nKau megah bagiku\r\n\r\n\r\nVerse 2\r\nSeg\'nap jiwa dan pengharapan\r\nT\'lah kuserahkan \'tuk rencana-Mu, Tuhan\r\n\'Kau Raja atasku\r\n\r\n\r\nPre-Chorus\r\nHanya \'Kau yang layak di tinggikan\r\n\r\n\r\nChorus 1\r\nAjaib \'Kau Tuhan\r\nAgung dan perkasa\r\n\'Kau sumber kemenanganku\r\n\r\n\r\nChorus 2\r\nLayak berkuasa\r\nMem\'rintah s\'lamanya\r\nYesus Kaulah Raja mulia', NULL, NULL, 'songs/pdf/ZM46LOyyVEG3M6ArytdokDlltlN6zM9DAM2T3XqI.pdf', 1, 0, 1, 0, '2026-08-20 12:24:01', '2026-08-20 12:24:52');
